CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;
CREATE TABLE "Account" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Email" character varying(256) NOT NULL,
    "PasswordHash" character varying(1024) NOT NULL,
    "Role" character varying(32) NOT NULL,
    "IsActive" boolean NOT NULL,
    "IsDeleted" boolean NOT NULL,
    "MustChangePassword" boolean NOT NULL,
    "FailedLoginCount" integer NOT NULL,
    "LockoutEnd" timestamp with time zone,
    "CreatedAt" timestamp with time zone NOT NULL,
    "LastLoginAt" timestamp with time zone,
    CONSTRAINT "PK_Account" PRIMARY KEY ("Id")
);

CREATE TABLE "Category" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" character varying(256) NOT NULL,
    "IsActive" boolean NOT NULL,
    CONSTRAINT "PK_Category" PRIMARY KEY ("Id")
);

CREATE TABLE "Preference" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" character varying(256) NOT NULL,
    "IsActive" boolean NOT NULL,
    CONSTRAINT "PK_Preference" PRIMARY KEY ("Id")
);

CREATE TABLE "Supplier" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" character varying(256) NOT NULL,
    "Phone" character varying(32),
    "Email" character varying(256),
    "IsActive" boolean NOT NULL,
    "IsDeleted" boolean NOT NULL,
    CONSTRAINT "PK_Supplier" PRIMARY KEY ("Id")
);

CREATE TABLE "ActivityLog" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "AccountId" integer,
    "Action" character varying(256) NOT NULL,
    "EntityType" character varying(256) NOT NULL,
    "EntityId" integer,
    "Detail" character varying(4000),
    "CreatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_ActivityLog" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_ActivityLog_Account_AccountId" FOREIGN KEY ("AccountId") REFERENCES "Account" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "CustomerProfile" (
    "AccountId" integer NOT NULL,
    "FullName" character varying(256) NOT NULL,
    "FullNameNormalized" character varying(256) NOT NULL,
    "Phone" character varying(32),
    "DateOfBirth" date,
    "Gender" character varying(32),
    "Address" character varying(1000),
    "ConsentPersonalData" boolean NOT NULL,
    CONSTRAINT "PK_CustomerProfile" PRIMARY KEY ("AccountId"),
    CONSTRAINT "FK_CustomerProfile_Account_AccountId" FOREIGN KEY ("AccountId") REFERENCES "Account" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "Notification" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "AccountId" integer NOT NULL,
    "Type" character varying(256) NOT NULL,
    "Title" character varying(256) NOT NULL,
    "RefType" character varying(256) NOT NULL,
    "RefId" integer NOT NULL,
    "IsRead" boolean NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_Notification" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Notification_Account_AccountId" FOREIGN KEY ("AccountId") REFERENCES "Account" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "PasswordResetToken" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "AccountId" integer NOT NULL,
    "TokenHash" character varying(128) NOT NULL,
    "ExpiresAt" timestamp with time zone NOT NULL,
    "UsedAt" timestamp with time zone,
    CONSTRAINT "PK_PasswordResetToken" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_PasswordResetToken_Account_AccountId" FOREIGN KEY ("AccountId") REFERENCES "Account" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "RefreshToken" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "AccountId" integer NOT NULL,
    "TokenHash" character varying(128) NOT NULL,
    "ExpiresAt" timestamp with time zone NOT NULL,
    "RevokedAt" timestamp with time zone,
    CONSTRAINT "PK_RefreshToken" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_RefreshToken_Account_AccountId" FOREIGN KEY ("AccountId") REFERENCES "Account" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "StaffProfile" (
    "AccountId" integer NOT NULL,
    "FullName" character varying(256) NOT NULL,
    "Phone" character varying(32),
    "Position" character varying(256),
    CONSTRAINT "PK_StaffProfile" PRIMARY KEY ("AccountId"),
    CONSTRAINT "FK_StaffProfile_Account_AccountId" FOREIGN KEY ("AccountId") REFERENCES "Account" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "Product" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" character varying(256) NOT NULL,
    "NameNormalized" character varying(256) NOT NULL,
    "Description" character varying(4000) NOT NULL,
    "Ingredients" character varying(4000) NOT NULL,
    "Benefits" character varying(4000) NOT NULL,
    "Usage" character varying(4000) NOT NULL,
    "CategoryId" integer NOT NULL,
    "SupplierId" integer,
    "Status" character varying(32) NOT NULL,
    "IsDeleted" boolean NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_Product" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Product_Category_CategoryId" FOREIGN KEY ("CategoryId") REFERENCES "Category" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Product_Supplier_SupplierId" FOREIGN KEY ("SupplierId") REFERENCES "Supplier" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "CustomerPreference" (
    "CustomerId" integer NOT NULL,
    "PreferenceId" integer NOT NULL,
    CONSTRAINT "PK_CustomerPreference" PRIMARY KEY ("CustomerId", "PreferenceId"),
    CONSTRAINT "FK_CustomerPreference_CustomerProfile_CustomerId" FOREIGN KEY ("CustomerId") REFERENCES "CustomerProfile" ("AccountId") ON DELETE RESTRICT,
    CONSTRAINT "FK_CustomerPreference_Preference_PreferenceId" FOREIGN KEY ("PreferenceId") REFERENCES "Preference" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "Survey" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Title" character varying(256) NOT NULL,
    "Description" character varying(4000),
    "Purpose" character varying(32) NOT NULL,
    "Status" character varying(32) NOT NULL,
    "OpenAt" timestamp with time zone,
    "CloseAt" timestamp with time zone,
    "CreatedBy" integer NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "IsDeleted" boolean NOT NULL,
    CONSTRAINT "PK_Survey" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_Survey_Dates" CHECK ("CloseAt" >= "OpenAt"),
    CONSTRAINT "FK_Survey_StaffProfile_CreatedBy" FOREIGN KEY ("CreatedBy") REFERENCES "StaffProfile" ("AccountId") ON DELETE RESTRICT
);

CREATE TABLE "Feedback" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "CustomerId" integer NOT NULL,
    "ProductId" integer NOT NULL,
    "Rating" integer NOT NULL,
    "Content" character varying(1000) NOT NULL,
    "Status" character varying(32) NOT NULL,
    "AcceptedBy" integer,
    "AcceptedAt" timestamp with time zone,
    "AssignedStaffId" integer,
    "RepliedAt" timestamp with time zone,
    "ClosedAt" timestamp with time zone,
    "CreatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_Feedback" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_Feedback_Rating" CHECK ("Rating" BETWEEN 1 AND 5),
    CONSTRAINT "FK_Feedback_CustomerProfile_CustomerId" FOREIGN KEY ("CustomerId") REFERENCES "CustomerProfile" ("AccountId") ON DELETE RESTRICT,
    CONSTRAINT "FK_Feedback_Product_ProductId" FOREIGN KEY ("ProductId") REFERENCES "Product" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Feedback_StaffProfile_AcceptedBy" FOREIGN KEY ("AcceptedBy") REFERENCES "StaffProfile" ("AccountId") ON DELETE RESTRICT,
    CONSTRAINT "FK_Feedback_StaffProfile_AssignedStaffId" FOREIGN KEY ("AssignedStaffId") REFERENCES "StaffProfile" ("AccountId") ON DELETE RESTRICT
);

CREATE TABLE "ProductPreference" (
    "ProductId" integer NOT NULL,
    "PreferenceId" integer NOT NULL,
    CONSTRAINT "PK_ProductPreference" PRIMARY KEY ("ProductId", "PreferenceId"),
    CONSTRAINT "FK_ProductPreference_Preference_PreferenceId" FOREIGN KEY ("PreferenceId") REFERENCES "Preference" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_ProductPreference_Product_ProductId" FOREIGN KEY ("ProductId") REFERENCES "Product" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "ProductVariant" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "ProductId" integer NOT NULL,
    "Name" character varying(256) NOT NULL,
    "Sku" character varying(100) NOT NULL,
    "Price" numeric(18,2) NOT NULL,
    "ImageUrl" character varying(2048),
    "IsDeleted" boolean NOT NULL,
    CONSTRAINT "PK_ProductVariant" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_ProductVariant_Price" CHECK ("Price" > 0),
    CONSTRAINT "FK_ProductVariant_Product_ProductId" FOREIGN KEY ("ProductId") REFERENCES "Product" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "SurveyQuestion" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "SurveyId" integer NOT NULL,
    "Text" character varying(1000) NOT NULL,
    "Type" character varying(32) NOT NULL,
    "IsRequired" boolean NOT NULL,
    "SortOrder" integer NOT NULL,
    CONSTRAINT "PK_SurveyQuestion" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_SurveyQuestion_Survey_SurveyId" FOREIGN KEY ("SurveyId") REFERENCES "Survey" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "SurveyRecipient" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "SurveyId" integer NOT NULL,
    "CustomerId" integer NOT NULL,
    "SentAt" timestamp with time zone NOT NULL,
    "Status" character varying(32) NOT NULL,
    "CompletedAt" timestamp with time zone,
    CONSTRAINT "PK_SurveyRecipient" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_SurveyRecipient_CustomerProfile_CustomerId" FOREIGN KEY ("CustomerId") REFERENCES "CustomerProfile" ("AccountId") ON DELETE RESTRICT,
    CONSTRAINT "FK_SurveyRecipient_Survey_SurveyId" FOREIGN KEY ("SurveyId") REFERENCES "Survey" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "SurveyResponse" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "SurveyId" integer NOT NULL,
    "CustomerId" integer NOT NULL,
    "SubmittedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_SurveyResponse" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_SurveyResponse_CustomerProfile_CustomerId" FOREIGN KEY ("CustomerId") REFERENCES "CustomerProfile" ("AccountId") ON DELETE RESTRICT,
    CONSTRAINT "FK_SurveyResponse_Survey_SurveyId" FOREIGN KEY ("SurveyId") REFERENCES "Survey" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "FeedbackAssignment" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "FeedbackId" integer NOT NULL,
    "StaffId" integer NOT NULL,
    "AssignedBy" integer NOT NULL,
    "AssignedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_FeedbackAssignment" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_FeedbackAssignment_Feedback_FeedbackId" FOREIGN KEY ("FeedbackId") REFERENCES "Feedback" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_FeedbackAssignment_StaffProfile_AssignedBy" FOREIGN KEY ("AssignedBy") REFERENCES "StaffProfile" ("AccountId") ON DELETE RESTRICT,
    CONSTRAINT "FK_FeedbackAssignment_StaffProfile_StaffId" FOREIGN KEY ("StaffId") REFERENCES "StaffProfile" ("AccountId") ON DELETE RESTRICT
);

CREATE TABLE "FeedbackReply" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "FeedbackId" integer NOT NULL,
    "StaffId" integer NOT NULL,
    "Content" character varying(4000) NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_FeedbackReply" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_FeedbackReply_Feedback_FeedbackId" FOREIGN KEY ("FeedbackId") REFERENCES "Feedback" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_FeedbackReply_StaffProfile_StaffId" FOREIGN KEY ("StaffId") REFERENCES "StaffProfile" ("AccountId") ON DELETE RESTRICT
);

CREATE TABLE "QuestionOption" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "QuestionId" integer NOT NULL,
    "Text" character varying(1000) NOT NULL,
    "SortOrder" integer NOT NULL,
    CONSTRAINT "PK_QuestionOption" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_QuestionOption_SurveyQuestion_QuestionId" FOREIGN KEY ("QuestionId") REFERENCES "SurveyQuestion" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "SurveyAnswer" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "ResponseId" integer NOT NULL,
    "QuestionId" integer NOT NULL,
    "OptionId" integer,
    "NumericValue" numeric(18,2),
    "TextValue" character varying(1000),
    CONSTRAINT "PK_SurveyAnswer" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_SurveyAnswer_QuestionOption_OptionId" FOREIGN KEY ("OptionId") REFERENCES "QuestionOption" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_SurveyAnswer_SurveyQuestion_QuestionId" FOREIGN KEY ("QuestionId") REFERENCES "SurveyQuestion" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_SurveyAnswer_SurveyResponse_ResponseId" FOREIGN KEY ("ResponseId") REFERENCES "SurveyResponse" ("Id") ON DELETE RESTRICT
);

